// Formula parsing and evaluation. Values: number, string, boolean, null (empty), or an error string starting with "#".
import { parseAddr, toAddr } from "./addr.mjs";

const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|([$A-Za-z_][$A-Za-z0-9_.]*)|(<=|>=|<>|[-+*\/^&=<>():,]))/y;
const REF = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*$/;

function tokenize(text) {
  const toks = [];
  let pos = 0;
  while (true) {
    const ws = /\s*/y;
    ws.lastIndex = pos;
    ws.exec(text);
    pos = ws.lastIndex;
    if (pos >= text.length) break;
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected character '${text[pos]}' at ${pos}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) toks.push({ t: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) toks.push({ t: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) toks.push({ t: "word", v: m[3] });
    else toks.push({ t: "op", v: m[4] });
  }
  return toks;
}

const normRef = (s) => s.replace(/\$/g, "").toUpperCase();

// Parses formula text (without the leading "=") into an AST. Throws SyntaxError on bad syntax.
export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const isOp = (...ops) => toks[i] && toks[i].t === "op" && ops.includes(toks[i].v);
  const expect = (op) => {
    if (!isOp(op)) throw new SyntaxError(`expected '${op}'`);
    i++;
  };

  function binary(next, ops) {
    let left = next();
    while (isOp(...ops)) {
      const op = toks[i++].v;
      left = { type: "bin", op, left, right: next() };
    }
    return left;
  }
  const comparison = () => binary(concat, ["=", "<>", "<", ">", "<=", ">="]);
  const concat = () => binary(additive, ["&"]);
  const additive = () => binary(term, ["+", "-"]);
  const term = () => binary(power, ["*", "/"]);
  const power = () => binary(unary, ["^"]);
  function unary() {
    if (isOp("-", "+")) {
      const op = toks[i++].v;
      return { type: "unary", op, arg: unary() };
    }
    return primary();
  }
  function primary() {
    const tok = toks[i];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    i++;
    if (tok.t === "num") return { type: "num", value: tok.v };
    if (tok.t === "str") return { type: "str", value: tok.v };
    if (tok.t === "op") {
      if (tok.v === "(") {
        const e = comparison();
        expect(")");
        return e;
      }
      throw new SyntaxError(`unexpected '${tok.v}'`);
    }
    const w = tok.v;
    if (isOp("(")) {
      i++;
      const args = [];
      if (!isOp(")")) {
        args.push(comparison());
        while (isOp(",")) {
          i++;
          args.push(comparison());
        }
      }
      expect(")");
      return { type: "call", name: w.toUpperCase(), args };
    }
    if (REF.test(w)) {
      if (isOp(":")) {
        i++;
        const t2 = toks[i];
        if (!t2 || t2.t !== "word" || !REF.test(t2.v)) throw new SyntaxError("bad range");
        i++;
        const a = parseAddr(w.replace(/\$/g, "")), b = parseAddr(t2.v.replace(/\$/g, ""));
        return {
          type: "range",
          c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col),
          r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row),
        };
      }
      return { type: "ref", addr: normRef(w) };
    }
    const u = w.toUpperCase();
    if (u === "TRUE") return { type: "bool", value: true };
    if (u === "FALSE") return { type: "bool", value: false };
    return { type: "name", name: u };
  }

  const ast = comparison();
  if (i < toks.length) throw new SyntaxError(`unexpected '${toks[i].v}'`);
  return ast;
}

function* rangeAddrs(n) {
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) yield toAddr(c, r);
}

// Normalized addresses (no $, upper case) the formula reads, ranges expanded row by row, each once, in order of first appearance.
export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    if (n.type === "ref") seen.add(n.addr);
    else if (n.type === "range") for (const a of rangeAddrs(n)) seen.add(a);
    else if (n.type === "bin") (walk(n.left), walk(n.right));
    else if (n.type === "unary") walk(n.arg);
    else if (n.type === "call") n.args.forEach(walk);
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUMRE = /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/;

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "string") {
    const t = v.trim();
    return NUMRE.test(t) ? Number(t) : "#VALUE!";
  }
  return v;
}
const fin = (x) => (typeof x === "number" && !Number.isFinite(x) ? "#NUM!" : x);

function toText(v) {
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "boolean") return v;
  const u = v.trim() === v ? v.toUpperCase() : v.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return "#VALUE!";
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

// Scales x by 10^k without binary floating-point error.
const shift = (x, k) => {
  const [m, e] = x.toExponential().split("e");
  return Number(`${m}e${Number(e) + k}`);
};

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  const r = shift(Math.round(shift(abs, d)), -d);
  return x < 0 ? -r : r;
}

// [min, max] argument counts
const ARITY = {
  IF: [2, 3], NOT: [1, 1], ROUND: [2, 2], ABS: [1, 1], LEN: [1, 1], UPPER: [1, 1], LOWER: [1, 1],
  SUM: [0, Infinity], AVERAGE: [0, Infinity], MIN: [0, Infinity], MAX: [0, Infinity], COUNT: [0, Infinity],
  AND: [1, Infinity], OR: [1, Infinity], CONCAT: [0, Infinity],
};

// The formula's value. lookup(addr) returns a cell's value for a normalized address, null for an empty cell.
export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.type) {
      case "num": case "str": case "bool": return n.value;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "name": return "#NAME?";
      case "unary": {
        const v = toNum(ev(n.arg));
        if (isErr(v)) return v;
        return n.op === "-" ? fin(-v) : v;
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  function binary(n) {
    const a = ev(n.left);
    if (isErr(a)) return a;
    const b = ev(n.right);
    if (isErr(b)) return b;
    switch (n.op) {
      case "&": return toText(a) + toText(b);
      case "=": return compare(a, b) === 0;
      case "<>": return compare(a, b) !== 0;
      case "<": return compare(a, b) < 0;
      case ">": return compare(a, b) > 0;
      case "<=": return compare(a, b) <= 0;
      case ">=": return compare(a, b) >= 0;
    }
    const x = toNum(a);
    if (isErr(x)) return x;
    const y = toNum(b);
    if (isErr(y)) return y;
    switch (n.op) {
      case "+": return fin(x + y);
      case "-": return fin(x - y);
      case "*": return fin(x * y);
      case "/": return y === 0 ? "#DIV/0!" : fin(x / y);
      case "^": return fin(Math.pow(x, y));
    }
  }

  // Calls fn(value, isDirect) for each argument value in order (ranges expanded); stops and returns an error if fn does.
  function each(args, fn) {
    for (const a of args) {
      if (a.type === "range") {
        for (const addr of rangeAddrs(a)) {
          const r = fn(lookup(addr), false);
          if (r !== undefined) return r;
        }
      } else {
        const r = fn(ev(a), true);
        if (r !== undefined) return r;
      }
    }
  }

  function call(n) {
    const arity = ARITY[n.name];
    if (!arity) return "#NAME?";
    const args = n.args;
    if (args.length < arity[0] || args.length > arity[1]) return "#VALUE!";
    switch (n.name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const nums = [];
        const err = each(args, (v, direct) => {
          if (isErr(v)) return v;
          if (direct) {
            const x = toNum(v);
            if (isErr(x)) return x;
            nums.push(x);
          } else if (typeof v === "number") nums.push(v);
        });
        if (err !== undefined) return err;
        if (n.name === "SUM") return fin(nums.reduce((s, x) => s + x, 0));
        if (n.name === "AVERAGE") return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return n.name === "MIN" ? Math.min(...nums) : Math.max(...nums);
      }
      case "COUNT": {
        let c = 0;
        each(args, (v) => { if (typeof v === "number") c++; });
        return c;
      }
      case "IF": {
        const c = toBool(ev(args[0]));
        if (isErr(c)) return c;
        if (c) return ev(args[1]);
        return args.length > 2 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        const and = n.name === "AND";
        let acc = and;
        const err = each(args, (v, direct) => {
          if (isErr(v)) return v;
          let b;
          if (direct) {
            b = toBool(v);
            if (isErr(b)) return b;
          } else if (typeof v === "number") b = v !== 0;
          else if (typeof v === "boolean") b = v;
          else return;
          acc = and ? acc && b : acc || b;
        });
        return err !== undefined ? err : acc;
      }
      case "NOT": {
        const b = toBool(ev(args[0]));
        return isErr(b) ? b : !b;
      }
      case "ROUND": {
        const x = toNum(ev(args[0]));
        if (isErr(x)) return x;
        const d = toNum(ev(args[1]));
        if (isErr(d)) return d;
        return fin(round(x, d));
      }
      case "ABS": {
        const x = toNum(ev(args[0]));
        return isErr(x) ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return n.name === "LEN" ? s.length : n.name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        const err = each(args, (v) => {
          if (isErr(v)) return v;
          out += toText(v);
        });
        return err !== undefined ? err : out;
      }
    }
  }

  return ev(ast);
}
