import { test } from "node:test";
import assert from "node:assert/strict";
import { parseFormula, refsOf, evaluate } from "../src/formula.mjs";

const cells = { A1: 1, A2: 2, B1: "x", B2: null, C1: "#DIV/0!" };
const run = (f) => evaluate(parseFormula(f), (a) => cells[a] ?? null);

test("operators and precedence", () => {
  assert.equal(run("-2^2"), 4);
  assert.equal(run("2^3^2"), 64);
  assert.equal(run('"a"&1+2&TRUE'), "a3TRUE");
  assert.equal(run("1/0"), "#DIV/0!");
  assert.equal(run('"abc"<"ABD"'), true);
  assert.equal(run("A1:A2"), "#VALUE!");
  assert.throws(() => parseFormula("1+"), SyntaxError);
});

test("functions", () => {
  assert.equal(run("SUM(A1:B2, 3)"), 6);
  assert.equal(run("sum(C1:C1)"), "#DIV/0!");
  assert.equal(run("COUNT(A1:B2)"), 2);
  assert.equal(run("ROUND(-2.5,0)"), -3);
  assert.equal(run("ROUND(1.005,2)"), 1.01);
  assert.equal(run("IF(TRUE,1,1/0)"), 1);
  assert.equal(run("FOO(1)"), "#NAME?");
  assert.equal(run("ABS()"), "#VALUE!");
});

test("refsOf", () => {
  assert.deepEqual(refsOf(parseFormula("$b$1+SUM(A1:B2)")), ["B1", "A1", "A2", "B2"]);
});
